INSERT IGNORE INTO dasha_faladesh (maha_id, antar_id, praty_id, interpretation_np, interpretation_en, positive_effects, challenges, career_indication, financial_indication, relationship_indication, classical_interpretation, sanskrit_reference, remedies) VALUES
(6,1,1,'महादशा शुक्रको अवधिमा वैवाहिक सुख, कला र भौतिक सुख बढ्छ, सौन्दर्य र सङ्गीतमा रुचि हुन्छ। अन्तर्दशा ग्रह सूर्य महादशा ग्रह शुक्रको शत्रु हुनाले यो अवधिमा तनाव र अवरोध आउन सक्छ। प्रत्यन्तर्दशा सूर्यले छोटो अवधिमा प्रतिष्ठा र पहिचानसम्बन्धी घटना देखाउँछ।',NULL,'विवाह, कला, सुख-साधन, प्रतिष्ठा, पदोन्नति','अति भोग, सम्बन्धमा सान्द्रता, अहंकार, स्वास्थ्य','कला, डिजाइन, मनोरञ्जन, प्रशासन','भौतिक सुख र सङ्गत आय, स्थिर आय, सम्मानजनक कमाई','जीवनसाथीसँग नजिक, प्रेम बढ्छ, परिवारमा आफ्नो मत माथि जिद','महादशायां शुक्रः अन्तरे सूर्यो प्रत्यन्ते सूर्यो फलं भवति।','Brihat Parashara Hora Shastra — Dasha Adhyaya','शुक्रबार लक्ष्मी मन्त्र जप र सुन्दरकाण्ड पाठ गर्ने। रविवार सूर्यलाई जल अर्पण र आदित्य हृदय स्तोत्र पाठ गर्ने।'),
(6,1,2,'महादशा शुक्रको अवधिमा वैवाहिक सुख, कला र भौतिक सुख बढ्छ, सौन्दर्य र सङ्गीतमा रुचि हुन्छ। अन्तर्दशा ग्रह सूर्य महादशा ग्रह शुक्रको शत्रु हुनाले यो अवधिमा तनाव र अवरोध आउन सक्छ। प्रत्यन्तर्दशा चन्द्रले छोटो अवधिमा भावना र पारिवारिक घटना देखाउँछ।',NULL,'विवाह, कला, सुख-साधन, प्रतिष्ठा, पदोन्नति','अति भोग, सम्बन्धमा सान्द्रता, अहंकार, स्वास्थ्य','कला, डिजाइन, मनोरञ्जन, प्रशासन','भौतिक सुख र सङ्गत आय, स्थिर आय, सम्मानजनक कमाई','जीवनसाथीसँग नजिक, प्रेम बढ्छ, परिवारमा आफ्नो मत माथि जिद','महादशायां शुक्रः अन्तरे सूर्यो प्रत्यन्ते चन्द्रो फलं भवति।','Brihat Parashara Hora Shastra — Dasha Adhyaya','शुक्रबार लक्ष्मी मन्त्र जप र सुन्दरकाण्ड पाठ गर्ने। रविवार सूर्यलाई जल अर्पण र आदित्य हृदय स्तोत्र पाठ गर्ने।'),
(6,1,3,'महादशा शुक्रको अवधिमा वैवाहिक सुख, कला र भौतिक सुख बढ्छ, सौन्दर्य र सङ्गीतमा रुचि हुन्छ। अन्तर्दशा ग्रह सूर्य महादशा ग्रह शुक्रको शत्रु हुनाले यो अवधिमा तनाव र अवरोध आउन सक्छ। प्रत्यन्तर्दशा मङ्गलले छोटो अवधिमा साहस र विवादसम्बन्धी घटना देखाउँछ।',NULL,'विवाह, कला, सुख-साधन, प्रतिष्ठा, पदोन्नति','अति भोग, सम्बन्धमा सान्द्रता, अहंकार, स्वास्थ्य','कला, डिजाइन, मनोरञ्जन, प्रशासन','भौतिक सुख र सङ्गत आय, स्थिर आय, सम्मानजनक कमाई','जीवनसाथीसँग नजिक, प्रेम बढ्छ, परिवारमा आफ्नो मत माथि जिद','महादशायां शुक्रः अन्तरे सूर्यो प्रत्यन्ते मङ्गलो फलं भवति।','Brihat Parashara Hora Shastra — Dasha Adhyaya','शुक्रबार लक्ष्मी मन्त्र जप र सुन्दरकाण्ड पाठ गर्ने। रविवार सूर्यलाई जल अर्पण र आदित्य हृदय स्तोत्र पाठ गर्ने।'),
(6,1,4,'महादशा शुक्रको अवधिमा वैवाहिक सुख, कला र भौतिक सुख बढ्छ, सौन्दर्य र सङ्गीतमा रुचि हुन्छ। अन्तर्दशा ग्रह सूर्य महादशा ग्रह शुक्रको शत्रु हुनाले यो अवधिमा तनाव र अवरोध आउन सक्छ। प्रत्यन्तर्दशा बुधले छोटो अवधिमा व्यापार र सञ्चारका घटना देखाउँछ।',NULL,'विवाह, कला, सुख-साधन, प्रतिष्ठा, पदोन्नति','अति भोग, सम्बन्धमा सान्द्रता, अहंकार, स्वास्थ्य','कला, डिजाइन, मनोरञ्जन, प्रशासन','भौतिक सुख र सङ्गत आय, स्थिर आय, सम्मानजनक कमाई','जीवनसाथीसँग नजिक, प्रेम बढ्छ, परिवारमा आफ्नो मत माथि जिद','महादशायां शुक्रः अन्तरे सूर्यो प्रत्यन्ते बुधो फलं भवति।','Brihat Parashara Hora Shastra — Dasha Adhyaya','शुक्रबार लक्ष्मी मन्त्र जप र सुन्दरकाण्ड पाठ गर्ने। रविवार सूर्यलाई जल अर्पण र आदित्य हृदय स्तोत्र पाठ गर्ने।'),
